const POLICY = { auto_approve_max_minor: 500000, auto_approve_currencies: ["INR"] };
const NOW = 1731920000;
const ev = (id: string, type = "refund.requested", data = {}) => ({
  event_id: id, type, created: NOW,
  data: { refund_id: "rf_1", payment_id: "pay_1", amount: 500000, currency: "INR", ...data },
});
// Independent signing implementation to avoid testing the verifier against itself.
const mac = (body: string | Buffer, timestamp: number, secret = SECRET) =>
  createHmac("sha256", secret).update(`${timestamp}.`).update(body).digest("hex");
const signature = (body: string | Buffer, timestamp = Math.floor(Date.now() / 1000)) =>
  `t=${timestamp},v1=${mac(body, timestamp)}`;

function snapshot(dir: string): Record<string, string> {
  return Object.fromEntries(readdirSync(dir, { recursive: true, withFileTypes: true })
    .filter(entry => entry.isFile())
    .map(entry => {
      const path = join(entry.parentPath, entry.name);
      return [path.slice(dir.length), readFileSync(path, "utf8")];
    }));
}

async function withApp(run: (ctx: {
  dir: string; store: Store;
  post: (body: string, headers?: Record<string, string>) => Promise<Response>;
}) => Promise<void>) {
  const dir = mkdtempSync(join(tmpdir(), "pay381-"));
  let server: Server | undefined;
  try {
    const store = new Store(dir);
    const app = buildApp(store, { roles: {}, principals: {} }, POLICY, {
      webhook_secrets: ["retired-secret", SECRET], tolerance_s: 300,
      // A legacy setting must not widen the replay authentication window.
      replay_tolerance_s: 86400,
    });
    server = createServer((req, res) => void app(req, res));
    await new Promise<void>(resolve => server!.listen(0, "127.0.0.1", resolve));
    const url = `http://127.0.0.1:${(server.address() as AddressInfo).port}/webhooks/paygate`;
    await run({ dir, store, post: (body, headers = {}) => fetch(url, {
      method: "POST", headers: { "content-type": "application/json", ...headers }, body,
    }) });
  } finally {
    if (server?.listening) await new Promise<void>((resolve, reject) => server!.close(err => err ? reject(err) : resolve()));
    rmSync(dir, { recursive: true, force: true });
  }
}

test("HMAC covers exact bytes and supports any signature/secret pairing", () => {
  const body = Buffer.from(' { "message": "₹5,000", "amount": 500000 }\n');
  assert.equal(computeSignature(SECRET, NOW, body), mac(body, NOW));
  const header = `t=${NOW},v1=${mac(body, NOW, "other")},v1=${mac(body, NOW)}`;
  assert.doesNotThrow(() => verifyWebhook(body, header, ["old", SECRET], NOW));
  assert.doesNotThrow(() => verifyWebhook(body, header, [SECRET, "old"], NOW));
  assert.throws(() => verifyWebhook(JSON.stringify(JSON.parse(body.toString())), header, [SECRET], NOW), SignatureError);
  assert.throws(() => verifyWebhook(Buffer.concat([body, Buffer.from(" ")]), header, [SECRET], NOW), SignatureError);
  assert.throws(() => verifyWebhook(body, header, [], NOW), SignatureError);
});

test("normal and replay timestamps have symmetric inclusive tolerance boundaries", () => {
  const body = JSON.stringify(ev("evt_time"));
  for (const offset of [-301, -300, 0, 300, 301]) {
    const ts = NOW + offset;
    const check = () => verifyWebhook(body, signature(body, ts), [SECRET], NOW);
    const replay = () => verifyReplay(body, String(ts), `v1=${mac(body, ts)}`, [SECRET], NOW);
    if (Math.abs(offset) <= 300) {
      assert.doesNotThrow(check);
      assert.doesNotThrow(replay);
    } else {
      assert.throws(check, SignatureError);
      assert.throws(replay, SignatureError);
    }
  }
});

test("malformed, missing and ambiguous signature headers fail closed", () => {
  const body = "{}";
  for (const header of [undefined, "", `t=${NOW}`, `v1=${mac(body, NOW)}`,
    `t=no,v1=${mac(body, NOW)}`, `t=${NOW},t=${NOW},v1=${mac(body, NOW)}`,
    `t=99999999999999999999,v1=${mac(body, NOW)}`, `t=${NOW},v1=ab`,
    `t=${NOW},v1=${"A".repeat(64)}`, `t=${NOW},v1=${"z".repeat(64)}`]) {
    assert.throws(() => verifyWebhook(body, header, [SECRET], NOW), SignatureError);
  }
  assert.throws(() => verifyReplay(body, `${NOW},v1=${mac(body, NOW)}`, "v1=bad", [SECRET], NOW), SignatureError);
  assert.throws(() => verifyReplay(body, String(NOW), `t=${NOW},v1=${mac(body, NOW)}`, [SECRET], NOW), SignatureError);
});

test("HTTP rejects unauthenticated deliveries without changing any state", async () => {
  await withApp(async ({ dir, post }) => {
    const before = snapshot(dir);
    const body = JSON.stringify(ev("evt_rejected"));
    const now = Math.floor(Date.now() / 1000);
    const valid = signature(body, now);
    const headersToReject = [
      {},
      { "paygate-signature": `t=${now},v1=${mac(body, now, "wrong")}` },
      { "paygate-signature": signature(body, now - 3600) },
      { "paygate-signature": valid, "x-replay-timestamp": String(now) },
      { "paygate-signature": valid, "x-replay-timestamp": String(now), "x-replay-signature": `v1=${"0".repeat(64)}` },
      { "paygate-signature": valid, "x-replay-timestamp": String(now - 3600), "x-replay-signature": `v1=${mac(body, now - 3600)}` },
      { "paygate-signature": valid, "x-replay-timestamp": String(now + 3600), "x-replay-signature": `v1=${mac(body, now + 3600)}` },
      { "paygate-signature": valid, "x-replay-timestamp": "", "x-replay-signature": `v1=${mac(body, now)}` },
    ];
    for (const headers of headersToReject) {
      const response = await post(body, headers);
      assert.equal(response.status, 401, JSON.stringify(headers));
      await response.json();
      assert.deepEqual(snapshot(dir), before);
    }
    const response = await post(body + " ", { "paygate-signature": valid });
    assert.equal(response.status, 401);
    await response.json();
    assert.deepEqual(snapshot(dir), before);
  });
});

test("HTTP returns 400 for signed invalid events without committing them", async () => {
  await withApp(async ({ dir, post }) => {
    const before = snapshot(dir);
    for (const body of ["not json", "null", "{}", JSON.stringify(ev("", "refund.requested")),
      JSON.stringify({ ...ev("evt_invalid"), created: "bad" }),
      JSON.stringify(ev("evt_invalid", "refund.requested", { amount: -1 })),
      JSON.stringify(ev("evt_invalid", "refund.requested", { amount: 1.5 })),
      JSON.stringify(ev("evt_invalid", "refund.requested", { currency: null })),
      JSON.stringify(ev("evt_invalid", "refund.cancelled", { refund_id: null }))]) {
      const response = await post(body, { "paygate-signature": signature(body) });
      assert.equal(response.status, 400, body);
      await response.json();
      assert.deepEqual(snapshot(dir), before);
    }
  });
});

test("replays authenticate independently and duplicates leave all files unchanged", async () => {
  await withApp(async ({ dir, store, post }) => {
    const body = JSON.stringify(ev("evt_replay"), null, 2) + "\n";
    const now = Math.floor(Date.now() / 1000);
    const replayHeaders = {
      "paygate-signature": "not even a valid original signature",
      "x-replay-timestamp": String(now), "x-replay-signature": `v1=${mac(body, now)}`,
    };
    const first = await post(body, replayHeaders);
    assert.equal(first.status, 200);
    assert.deepEqual(await first.json(), { received: true, duplicate: false });
    const before = snapshot(dir);
    for (const headers of [replayHeaders, { "paygate-signature": signature(body) }]) {
      const second = await post(body, headers);
      assert.equal(second.status, 200);
      assert.deepEqual(await second.json(), { received: true, duplicate: true });
      assert.deepEqual(snapshot(dir), before);
    }
    // Even a newly signed, changed payload with this ID cannot overwrite the original.
    const changed = JSON.stringify(ev("evt_replay", "refund.requested", { amount: 1 }));
    assert.deepEqual(await (await post(changed, { "paygate-signature": signature(changed) })).json(),
      { received: true, duplicate: true });
    assert.deepEqual(snapshot(dir), before);
    assert.equal(store.listRefunds().length, 1);
    const restarted = new Store(dir);
    assert.equal(processEvent(restarted, POLICY, parseEvent(body)).outcome, "duplicate");
    assert.deepEqual(snapshot(dir), before);
  });
});

test("concurrent retries process one event only", async () => {
  await withApp(async ({ store, post }) => {
    const body = JSON.stringify(ev("evt_concurrent"));
    const results = await Promise.all(Array.from({ length: 8 }, async () => {
      const response = await post(body, { "paygate-signature": signature(body) });
      assert.equal(response.status, 200);
      return response.json();
    }));
    assert.equal(results.filter(result => !result.duplicate).length, 1);
    assert.equal(store.listRefunds().length, 1);
  });
});

test("ignored types and cancellation audits are idempotent", async () => {
  await withApp(async ({ dir, store, post }) => {
    const deliver = async (body: string) => {
      const response = await post(body, { "paygate-signature": signature(body) });
      assert.equal(response.status, 200);
      return response.json();
    };
    const ignored = JSON.stringify({ event_id: "evt_ignored", type: "payment.updated", created: NOW });
    assert.equal((await deliver(ignored)).duplicate, false);
    let before = snapshot(dir);
    assert.equal((await deliver(ignored)).duplicate, true);
    assert.deepEqual(snapshot(dir), before);
    await deliver(JSON.stringify(ev("evt_requested")));
    const cancellation = JSON.stringify(ev("evt_cancel", "refund.cancelled"));
    assert.equal((await deliver(cancellation)).duplicate, false);
    assert.equal(store.listRefunds()[0].status, "auto_approved");
    assert.match(readFileSync(join(dir, "audit.jsonl"), "utf8"), /cancel.ignored/);
    before = snapshot(dir);
    assert.equal((await deliver(cancellation)).duplicate, true);
    assert.deepEqual(snapshot(dir), before);
  });
});

test("event IDs that match object properties are handled and persist correctly", async () => {
  await withApp(async ({ dir, store }) => {
    for (const id of ["toString", "constructor", "__proto__"]) {
      assert.equal(processEvent(store, POLICY, parseEvent(JSON.stringify(ev(id)))).outcome, "processed");
      assert.equal(processEvent(new Store(dir), POLICY, parseEvent(JSON.stringify(ev(id)))).outcome, "duplicate");
    }
    assert.equal(store.listRefunds().length, 3);
  });
});

test("configured policy implements Dana's inclusive INR 5,000 threshold", () => {
  const policy = JSON.parse(readFileSync(new URL("../config/refunds.json", import.meta.url), "utf8"));
  assert.equal(policy.auto_approve_max_minor, 500000);
  assert.deepEqual(policy.auto_approve_currencies, ["INR"]);
  assert.equal(decideStatus(policy, 500000, "INR"), "auto_approved");
  assert.equal(decideStatus(policy, 500001, "INR"), "pending_review");
  assert.equal(decideStatus(policy, 1, "USD"), "pending_review");
});
